<?php use App\Models\DB; ?>
<div class="page-heading"><div><div class="eyebrow">MY STORE OPERATIONS</div><h1><?= e(ucfirst($section)) ?><span class="green">.</span></h1><p>Keep the marketplace trusted, transparent and running smoothly.</p></div></div>
<?php if($section==='overview'):$stats=DB::one('SELECT (SELECT COUNT(*) FROM users WHERE role="retailer") retailers,(SELECT COUNT(*) FROM users WHERE role="wholesaler") wholesalers,(SELECT COUNT(*) FROM supplier_orders) orders,(SELECT COUNT(*) FROM businesses b JOIN users u ON u.id=b.user_id WHERE u.role="wholesaler" AND b.status="pending") pending,(SELECT COALESCE(SUM(subtotal),0) FROM checkouts WHERE status IN ("paid","partially_refunded","refunded")) sales,(SELECT COALESCE(SUM(fee),0) FROM checkouts WHERE status IN ("paid","partially_refunded","refunded")) fees,(SELECT COALESCE(SUM(r.merchandise),0) FROM refunds r JOIN supplier_orders o ON o.id=r.order_id JOIN checkouts c ON c.id=o.checkout_id WHERE r.status="succeeded" AND c.mode="stripe") refunded_sales,(SELECT COALESCE(SUM(r.fee),0) FROM refunds r JOIN supplier_orders o ON o.id=r.order_id JOIN checkouts c ON c.id=o.checkout_id WHERE r.status="succeeded" AND c.mode="stripe") refunded_fees');?><div class="stats-grid"><?php foreach(['retailers'=>'Retailers','wholesalers'=>'Wholesalers','orders'=>'Supplier orders','pending'=>'Pending approvals','sales'=>'Net merchandise sales','fees'=>'Net collected buyer fees'] as $key=>$label):?><div class="stat-card"><span><?= $label ?></span><strong><?= in_array($key,['sales','fees'])?money($stats[$key]-$stats['refunded_'.$key]):$stats[$key] ?></strong></div><?php endforeach;?></div><div class="soft-note">Sales and collected fee metrics exclude demo transactions and subtract confirmed refunds. Demo orders are visible in order and payment lists.</div><div class="two-column"><section class="panel"><h2>Businesses awaiting approval</h2><p><?= $stats['pending'] ?> supplier applications to review.</p><a class="btn btn-primary" href="/admin/users">Review businesses →</a></section><section class="panel"><h2>Marketplace settings</h2><p>Buyer fee <?= DB::setting('buyer_fee_bps','50')/100 ?>% · tax <?= DB::setting('tax_bps','0')/100 ?>% · <?= e(DB::setting('currency','USD')) ?></p><a class="btn btn-outline-secondary" href="/admin/settings">Manage settings</a></section></div>
<?php elseif($section==='users'):$users=DB::all('SELECT u.id,u.email,u.role,u.active,u.verified_at,b.name,b.status,f.stripe_account FROM users u JOIN businesses b ON b.user_id=u.id LEFT JOIN fulfillment_settings f ON f.supplier_id=u.id ORDER BY b.status="pending" DESC,u.id DESC');?><div class="table-panel"><table><thead><tr><th>Business</th><th>Role</th><th>Email / verification</th><th>Approval / access</th><th>Connect test account</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><strong><?= e($u['name']) ?></strong></td><td><?= e($u['role']) ?></td><td><?= e($u['email']) ?><small><?= $u['verified_at']?'Verified':'Unverified' ?></small></td><td><?php if($u['role']!=='admin'):?><form action="/admin/user" method="post" class="inline-form"><?= csrf() ?><input type="hidden" name="id" value="<?= $u['id'] ?>"><select name="status" aria-label="Approval status"><?php foreach(['pending','approved','suspended'] as $s):?><option <?= $s===$u['status']?'selected':'' ?>><?= $s ?></option><?php endforeach;?></select><label class="check-label"><input type="checkbox" name="active" <?= $u['active']?'checked':'' ?>> Active</label><button class="btn btn-primary btn-sm">Save</button></form><?php else:?>Protected administrator<?php endif;?></td><td><?php if($u['role']==='wholesaler'):?><form action="/admin/connect" method="post" class="inline-form"><?= csrf() ?><input type="hidden" name="id" value="<?= $u['id'] ?>"><input name="stripe_account" aria-label="Connected account ID" value="<?= e($u['stripe_account']) ?>" placeholder="acct_…"><button class="btn btn-outline-secondary btn-sm">Save</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($section==='catalog'):$categories=DB::all('SELECT * FROM categories ORDER BY name');$products=DB::all('SELECT * FROM products ORDER BY id');?><div class="two-column"><section class="panel"><h2>Categories</h2><?php foreach($categories as $c):?><form method="post" action="/admin/category" class="inline-form mb-3"><?= csrf() ?><input type="hidden" name="id" value="<?= $c['id'] ?>"><input name="name" aria-label="Category name" value="<?= e($c['name']) ?>" required maxlength="100"><button class="btn btn-outline-secondary btn-sm">Save</button></form><?php endforeach;?><form method="post" action="/admin/category" class="inline-form"><?= csrf() ?><input name="name" aria-label="New category" placeholder="New category" required maxlength="100"><button class="btn btn-primary">Add</button></form></section><form method="post" action="/admin/product" class="panel"><?= csrf() ?><h2>Add canonical product</h2><label>Category<select name="category_id"><?php foreach($categories as $c):?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach;?></select></label><?php foreach(['name'=>'Product name','brand'=>'Brand','sku'=>'SKU','gtin'=>'UPC / GTIN (optional)'] as $key=>$label):?><label><?= $label ?><input name="<?= $key ?>" <?= $key==='gtin'?'':'required' ?>></label><?php endforeach;?><label>Description<textarea name="description" maxlength="3000" rows="3"></textarea></label><button class="btn btn-primary">Add product</button></form></div><section class="panel"><h2>Canonical catalog</h2><?php foreach($products as $p):?><details><summary><?= e($p['name'].' · '.$p['sku']) ?></summary><form method="post" action="/admin/product"><?= csrf() ?><input type="hidden" name="id" value="<?= $p['id'] ?>"><div class="form-row"><?php foreach(['name','brand','sku','gtin'] as $key):?><label><?= e(ucfirst($key)) ?><input name="<?= $key ?>" value="<?= e($p[$key]) ?>" <?= $key==='gtin'?'':'required' ?>></label><?php endforeach;?></div><label>Category<select name="category_id"><?php foreach($categories as $c):?><option value="<?= $c['id'] ?>" <?= $c['id']===$p['category_id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach;?></select></label><label>Description<textarea name="description" rows="2"><?= e($p['description']) ?></textarea></label><button class="btn btn-primary btn-sm">Save product</button></form></details><?php endforeach;?></section><div class="table-panel"><table><thead><tr><th>Supplier offer</th><th>Product</th><th>Stock</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach(DB::all('SELECT o.*,p.name,b.name supplier FROM offers o JOIN products p ON p.id=o.product_id JOIN businesses b ON b.user_id=o.supplier_id') as $o):?><tr><td><?= e($o['supplier']) ?></td><td><?= e($o['name']) ?></td><td><?= $o['stock'] ?></td><td><?= $o['archived']?'Archived':'Active' ?></td><td><?php if(!$o['archived']):?><form action="/admin/listing" method="post"><?= csrf() ?><input type="hidden" name="id" value="<?= $o['id'] ?>"><button class="btn btn-outline-secondary btn-sm">Archive</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($section==='imports'):?><section class="panel"><h2>Authorized external price imports</h2><p>Use authorized APIs, licensed feeds or manually maintained CSV data. Sam’s Club demonstration prices are fictional and clearly labeled. External offers are informational, never cart items.</p><a href="/admin/import-template">Download CSV template →</a><form action="/admin/import" method="post" enctype="multipart/form-data" class="inline-form mt-3"><?= csrf() ?><label>Comparison CSV<input name="csv" type="file" accept=".csv,text/csv" required></label><button class="btn btn-primary">Import comparisons</button></form></section><div class="table-panel"><table><thead><tr><th>Source</th><th>Product</th><th>Price / pack</th><th>Data type</th><th>Updated</th><th></th></tr></thead><tbody><?php foreach(DB::all('SELECT e.*,s.name source,s.mode,p.name FROM external_offers e JOIN external_sources s ON s.id=e.source_id JOIN products p ON p.id=e.product_id ORDER BY e.id DESC') as $o):?><tr><td><?= e($o['source']) ?></td><td><?= e($o['name']) ?></td><td><?= e($o['currency']) ?> <?= number_format($o['price']/100,2) ?><small><?= e($o['pack_size'].' '.$o['unit']) ?></small></td><td><?= $o['mode']==='demo'?'Demonstration':'Imported, not live' ?></td><td><?= e($o['updated_at']) ?></td><td><form action="/admin/external/delete" method="post" data-confirm="Delete this comparison offer?"><?= csrf() ?><input type="hidden" name="id" value="<?= $o['id'] ?>"><button class="btn btn-outline-danger btn-sm">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div>
<?php elseif($section==='settings'):?><div class="two-column"><form method="post" action="/admin/setting" class="panel"><?= csrf() ?><h2>Marketplace pricing</h2><label>Currency<select name="currency"><?php foreach(['USD','EUR','GBP','CAD','AUD','PKR'] as $c):?><option <?= DB::setting('currency','USD')===$c?'selected':'' ?>><?= $c ?></option><?php endforeach;?></select></label><label>Buyer fee basis points (50 = 0.5%)<input name="buyer_fee_bps" type="number" min="0" max="1000" value="<?= e(DB::setting('buyer_fee_bps','50')) ?>" required></label><label>Tax basis points (0 = no tax)<input name="tax_bps" type="number" min="0" max="5000" value="<?= e(DB::setting('tax_bps','0')) ?>" required></label><label>Fee basis<select name="fee_basis"><option value="merchandise_after_discounts" <?= DB::setting('fee_basis')==='merchandise_after_discounts'?'selected':'' ?>>Merchandise after tier discounts, excluding delivery & tax</option><option value="merchandise_plus_delivery" <?= DB::setting('fee_basis')==='merchandise_plus_delivery'?'selected':'' ?>>Merchandise plus delivery, excluding tax</option></select></label><p class="small-muted">Default fee basis: merchandise after discounts. The optional delivery-inclusive basis applies to new orders only. Rounding: half-up, per supplier, in integer minor units. Currency changes are blocked after checkout history exists.</p><button class="btn btn-primary">Save settings</button></form><section class="panel"><h2>Integration status</h2><div class="total-row"><span>Payments</span><strong><?= e(App\services\Payment::mode()==='demo'?'Demo — no real charges':'Stripe test mode') ?></strong></div><div class="total-row"><span>Webhook secret</span><strong><?= env('STRIPE_WEBHOOK_SECRET')?'Configured':'Not configured' ?></strong></div><div class="total-row"><span>Email</span><strong><?= e(env('MAIL_MODE','log')==='log'?'Private local outbox':'PHP mail transport') ?></strong></div><div class="total-row"><span>Distance</span><strong><?= env('MAP_PROVIDER','none')==='mapbox' && env('MAP_API_KEY')?'Mapbox routes + fallback':'Straight-line estimates' ?></strong></div><p>Credentials are configured outside the public root in environment variables. Mapbox driving routes are optional; geocoding and authorized external supplier APIs require additional integrations. No credentials are shown here.</p></section></div>
<?php elseif($section==='audit'):?><div class="table-panel"><table><thead><tr><th>Time (UTC)</th><th>Administrator</th><th>Action</th><th>Entity</th></tr></thead><tbody><?php foreach(DB::all('SELECT a.*,b.name actor FROM audit_logs a JOIN businesses b ON b.user_id=a.actor_id ORDER BY a.id DESC LIMIT 200') as $a):?><tr><td><?= e($a['created_at']) ?></td><td><?= e($a['actor']) ?></td><td><?= e($a['action']) ?></td><td><?= e($a['entity']) ?></td></tr><?php endforeach;?></tbody></table></div><small>Most recent 200 administrative actions.</small>
<?php elseif($section==='payments'):?><div class="table-panel"><table><thead><tr><th>Checkout</th><th>Provider</th><th>Status</th><th>Collected amount</th><th>Refunds</th><th>Supplier orders</th></tr></thead><tbody><?php foreach(DB::all('SELECT p.*,COALESCE((SELECT SUM(r.amount) FROM refunds r JOIN supplier_orders o ON o.id=r.order_id WHERE o.checkout_id=p.checkout_id AND r.status="succeeded"),0) refunds FROM payments p ORDER BY p.id DESC LIMIT 200') as $p):?><tr><td>#<?= $p['checkout_id'] ?></td><td><span class="badge <?= $p['provider']==='demo'?'demo-badge':'soft-badge' ?>"><?= e($p['provider']) ?><?= $p['provider']==='demo'?' · no real money':' · test' ?></span></td><td><?= e($p['status']) ?></td><td><?= money($p['amount']) ?></td><td><?= money($p['refunds']) ?></td><td><?php foreach(DB::all('SELECT id FROM supplier_orders WHERE checkout_id=?',[$p['checkout_id']]) as $o):?><a href="/order?id=<?= $o['id'] ?>">Order #<?= $o['id'] ?> →</a><br><?php endforeach;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
